"""
[fogSpike]

The fog probe (TrigScript 4, S4): fog of war as a picture. Hand-written eudplib, made by probes/lib/fog-gen.mts. A brush is a
Map Revealer made on a tile and taken away in the same trigger pass, its sight range written just before it is made;
the vision countdown (1.16.1 0x51CE98) is written to 1 after each pass, so the next frame starts from a wiped board.

  A   2  one brush jumping between two places, countdown written: does the old place go dark at once?
  B  12  the same with the countdown NOT written: the old place should stay lit for up to four seconds
  C  22  the sizes, sight 1 to 6 (top row) and 7 to 11 (lower row), redrawn every frame
  D  32  one brush sliding a tile a frame: smooth, smeared, or trailing?
  E  42  four pictures, five seconds each: a dancer, an apple, "Bad Apple", the dancer white on black
  F  62  an animation (the dancer swaying, an apple pulsing), 72 frames looped
  G  82  the dancer painted 1, 2, 4 then 8 times a frame (5 seconds each): when does the game stutter?
  H 102  ground revealers (top row: sight 0, sight 1) beside air ones (lower row: sight 1)
"""
from eudplib import *

UNIT = "Map Revealer"
LOC = "Pixel"
SIGHT_EPD = EPD(0x663238 + 100)   # units.dat sight range: the unit (101) is byte 1 of this dword
SIGHT_SUBP = 1
FLAGS_UNIT = 0x664080 + 101 * 4   # units.dat flags of the unit; 0x4 = flyer
COUNTDOWN = 0x51CE98
DATA = Db(bytes.fromhex(""))
PICS = {"dancer":0,"apple":138,"text":223,"inverted":367}
ANIM = 456

f = EUDVariable()
anim = EUDVariable()
mv = EUDVariable()
toggle = EUDVariable()
tick = EUDVariable()


def u(s):
    return s.encode("utf-8")


def show(s):
    DoActions(DisplayText(u(s)))


@EUDFunc
def brush(x, y, r):
    left = x * 32
    top = y * 32
    f_setloc(LOC, left, top, left + 32, top + 32)
    f_bwrite_epd(SIGHT_EPD, SIGHT_SUBP, r)
    DoActions([CreateUnit(1, UNIT, LOC, P1), RemoveUnit(UNIT, P1)])


@EUDFunc
def paint(start):
    p = EUDVariable()
    p << start
    if EUDInfLoop()():
        v = f_dwread_epd(p)
        EUDBreakIf(v == 0xFFFFFFFF)
        p += 1
        w0, w1, bx, by, br, b3 = f_dwbreak(v)
        brush(bx, by, br)
    EUDEndInfLoop()
    EUDReturn(p + 1)


def center(tx, ty):
    f_setloc(LOC, tx * 32, ty * 32, tx * 32 + 32, ty * 32 + 32)
    DoActions(CenterView(LOC))


def during(a, b):
    return EUDIf()([f >= a, f < b])


def at(n):
    return EUDIf()(f == n)


def afterTriggerExec():
    f.__iadd__(1)
    if at(1):
        DoActions([RemoveUnit("(any unit)", P1), RemoveUnit("(any unit)", P2)])
        center(64, 48)
        show("\x04S4 fog probe. Watch the screen and the minimap; each step says what to look for.")
    EUDEndIf()
    # The questions, again half way through each step (lines fade after a few seconds).
    if EUDIf()([f.Exactly(48)]):
        show("\u0011A: one brush jumping between two places every half second. Does the old place go dark AT ONCE (screen and minimap)?")
    EUDEndIf()
    if EUDIf()([f.Exactly(168)]):
        show("\u0011A: one brush jumping between two places every half second. Does the old place go dark AT ONCE (screen and minimap)?")
    EUDEndIf()
    if EUDIf()([f.Exactly(288)]):
        show("\u0011B: the same, the countdown NOT written. The old place should stay lit for up to four seconds.")
    EUDEndIf()
    if EUDIf()([f.Exactly(408)]):
        show("\u0011B: the same, the countdown NOT written. The old place should stay lit for up to four seconds.")
    EUDEndIf()
    if EUDIf()([f.Exactly(528)]):
        show("\u0011C: brush sizes. Minimap: sight 1-6 top row, 7-11 lower row. Clean shapes? Same size each frame?")
    EUDEndIf()
    if EUDIf()([f.Exactly(648)]):
        show("\u0011C: brush sizes. Minimap: sight 1-6 top row, 7-11 lower row. Clean shapes? Same size each frame?")
    EUDEndIf()
    if EUDIf()([f.Exactly(768)]):
        show("\u0011D: one brush sliding a tile a frame. Smooth? Smeared? A trail behind it?")
    EUDEndIf()
    if EUDIf()([f.Exactly(888)]):
        show("\u0011D: one brush sliding a tile a frame. Smooth? Smeared? A trail behind it?")
    EUDEndIf()
    if EUDIf()([f.Exactly(1008)]):
        show("\u0011E: pictures, 5 s each: dancer, apple, 'Bad Apple', dancer white on black. How do they read on the minimap? On screen?")
    EUDEndIf()
    if EUDIf()([f.Exactly(1128)]):
        show("\u0011E: pictures, 5 s each: dancer, apple, 'Bad Apple', dancer white on black. How do they read on the minimap? On screen?")
    EUDEndIf()
    if EUDIf()([f.Exactly(1488)]):
        show("\u0011F: an animation, 72 frames looped. Smooth? Flicker? Tearing?")
    EUDEndIf()
    if EUDIf()([f.Exactly(1608)]):
        show("\u0011F: an animation, 72 frames looped. Smooth? Flicker? Tearing?")
    EUDEndIf()
    if EUDIf()([f.Exactly(1968)]):
        show("\u0011G: the dancer painted 1x, 2x, 4x, 8x a frame, 5 s each. When does the game slow down or stutter?")
    EUDEndIf()
    if EUDIf()([f.Exactly(2088)]):
        show("\u0011G: the dancer painted 1x, 2x, 4x, 8x a frame, 5 s each. When does the game slow down or stutter?")
    EUDEndIf()
    if EUDIf()([f.Exactly(2448)]):
        show("\u0011H: top row ground revealers (sight 0 then 1), lower row air (sight 1). Ground sight 0 should be a 3x3 square.")
    EUDEndIf()
    if EUDIf()([f.Exactly(2568)]):
        show("\u0011H: top row ground revealers (sight 0 then 1), lower row air (sight 1). Ground sight 0 should be a 3x3 square.")
    EUDEndIf()
    # A and B: toggle every 12 frames.
    if during(48, 528):
        tick.__iadd__(1)
        if EUDIf()(tick >= 12):
            tick << 0
            toggle << 1 - toggle
        EUDEndIf()
        if EUDIf()(toggle == 0):
            brush(56, 48, 5)
        if EUDElse()():
            brush(72, 48, 5)
        EUDEndIf()
    EUDEndIf()
    if during(528, 768):
        brush(5, 22, 1)
        brush(13, 22, 2)
        brush(23, 22, 3)
        brush(35, 22, 4)
        brush(49, 22, 5)
        brush(65, 22, 6)
        brush(11, 64, 7)
        brush(31, 64, 8)
        brush(53, 64, 9)
        brush(77, 64, 10)
        brush(103, 64, 11)
    EUDEndIf()
    if during(768, 1008):
        mv.__iadd__(1)
        if EUDIf()(mv >= 116):
            mv << 0
        EUDEndIf()
        brush(mv + 6, 48, 6)
    EUDEndIf()
    if during(1008, 1128):
        paint(EPD(DATA) + 0)
    EUDEndIf()
    if during(1128, 1248):
        paint(EPD(DATA) + 138)
    EUDEndIf()
    if during(1248, 1368):
        paint(EPD(DATA) + 223)
    EUDEndIf()
    if during(1368, 1488):
        paint(EPD(DATA) + 367)
    EUDEndIf()
    if at(1488):
        anim << EPD(DATA) + ANIM
    EUDEndIf()
    if during(1488, 1968):
        anim << paint(anim)
        if EUDIf()(f_dwread_epd(anim) == 0xFFFFFFFE):
            anim << EPD(DATA) + ANIM
        EUDEndIf()
    EUDEndIf()
    if during(1968, 2088):
        paint(EPD(DATA) + 0)
    EUDEndIf()
    if during(2088, 2208):
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
    EUDEndIf()
    if during(2208, 2328):
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
    EUDEndIf()
    if during(2328, 2448):
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
        paint(EPD(DATA) + 0)
    EUDEndIf()
    if at(2088):
        show("\x11G: 2x a frame")
    EUDEndIf()
    if at(2208):
        show("\x11G: 4x a frame")
    EUDEndIf()
    if at(2328):
        show("\x11G: 8x a frame")
    EUDEndIf()
    if during(2448, 2688):
        DoActions(SetMemoryX(FLAGS_UNIT, SetTo, 0, 4))
        brush(52, 40, 0)
        brush(68, 40, 1)
        DoActions(SetMemoryX(FLAGS_UNIT, SetTo, 4, 4))
        brush(52, 56, 1)
        brush(68, 56, 1)
    EUDEndIf()
    if at(2688):
        show("\x04Done. The fog stays as it was from here.")
    EUDEndIf()
    # B leaves the countdown alone; every other step asks for a wipe on the next frame.
    if EUDIfNot()([f >= 288, f < 528]):
        DoActions(SetMemory(COUNTDOWN, SetTo, 1))
    EUDEndIf()
